export const src = (id) => (D[id] ? P + D[id] : "");

/* 給「收藏」用的：對方送來的如果就是內建的那一張，不必再存一份到本機圖庫。
   ⚠️ 第一次呼叫才建 Set —— 一開房就建等於白算一次幾百 KB 的字串。 */
let seen = null;
export const isBuiltin = (u) => {
  if (!u) return false;
  if (!seen) seen = new Set(Object.values(D).map((b) => P + b));
  return seen.has(u);
};
